import { a as ProjectIOError } from "./project-writer-uYlUeseV.js";
import { t as PlatformIO } from "./platform-io-ClQeFKKN.js";
import * as fs from "node:fs/promises";
import * as path from "node:path";
//#region src/io/node-io.ts
/**
* Node.js I/O implementation for reading and writing FairyGUI projects.
*
* Usage:
*
* ```ts
* import { NodeIO } from '@openfairygui/core/node';
*
* const io = new NodeIO();
* const doc = await io.readProject('./path/to/project.fairy');
* await io.writeProject(doc, './path/to/output.fairy');
* const doc2 = await io.readBinary('./path/to/package_fui.bytes');
* ```
*
* @category I/O
*/
var NodeIO = class extends PlatformIO {
	createFileSystem() {
		return {
			resolvePath: (filePath) => fs.realpath(filePath),
			async readFile(filePath) {
				return fs.readFile(filePath, "utf-8");
			},
			async readFileRaw(filePath) {
				const buf = await fs.readFile(filePath);
				return new Uint8Array(buf.buffer, buf.byteOffset, buf.byteLength);
			},
			async writeFile(filePath, content) {
				await fs.writeFile(filePath, content, "utf-8");
			},
			async writeFileRaw(filePath, data) {
				await fs.writeFile(filePath, data);
			},
			async mkdir(dirPath) {
				await fs.mkdir(dirPath, { recursive: true });
			},
			async readdir(dirPath) {
				const entries = await fs.readdir(dirPath, { withFileTypes: true });
				const symlink = entries.find((entry) => entry.isSymbolicLink());
				if (symlink) throw new ProjectIOError(`Symbolic links are not supported in project directories: ${path.join(dirPath, symlink.name)}`);
				return entries.filter((entry) => entry.isDirectory()).map((entry) => entry.name);
			},
			async exists(filePath) {
				try {
					await fs.access(filePath);
					return true;
				} catch (error) {
					if (error.code === "ENOENT" || error.code === "ENOTDIR") return false;
					throw error;
				}
			},
			async unlink(filePath) {
				await fs.unlink(filePath);
			},
			async rmdir(dirPath) {
				await fs.rmdir(dirPath);
			},
			join(...paths) {
				return path.join(...paths);
			},
			dirname(filePath) {
				return path.dirname(filePath);
			}
		};
	}
};
//#endregion
export { NodeIO };
